import type { BuildPlan } from "../schema.js";
import type { LevelObject } from "./gameplay.js";

export function writeSpwn(plan: BuildPlan, objects: LevelObject[]): string {
  const lines = [
    "// Generated by gd-level-builder; deterministic source output.",
    `// Level: ${commentText(plan.name)} | Theme: ${commentText(plan.theme)}`,
    `// BPM: ${plan.bpm} | Sections: ${plan.sections.length} | Objects: ${objects.length}`,
    "",
    "extract obj_props",
    "",
    "// Reusable helper for placing an object and assigning its group.",
    "let place = (object_id: @number, x: @number, y: @number, group_id: @group) {",
    "    $.add(obj {",
    "        OBJ_ID: object_id,",
    "        X: x,",
    "        Y: y,",
    "        GROUPS: group_id,",
    "    })",
    "}",
    "",
    "// Object groups allocated by the BuildPlan.",
  ];

  for (const section of plan.sections) {
    lines.push(`// ${section.type.toUpperCase()} section: beats ${number(section.startBeat)}-${number(section.startBeat + section.durationBeats)}, group ${section.groupId}`);
    lines.push(`let section_${section.groupId} = ${section.groupId}g;`);
  }

  lines.push("", "// Generated gameplay and decoration.");
  for (const object of objects) {
    lines.push(`place(${object.objectId}, ${object.x}, ${object.y}, section_${object.groupId}); // ${object.kind}; ${number(object.duration)}s`);
  }
  return `${lines.join("\n")}\n`;
}

function commentText(text: string): string {
  return text.replace(/[\r\n]+/g, " ").replace(/\*\//g, "* /");
}

function number(value: number): string {
  return Number(value.toFixed(4)).toString();
}
